import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DpI_zlPE.js";var i=JSON.parse(`{"title":"AI","description":"","frontmatter":{},"headers":[],"relativePath":"ccc/AI.md","filePath":"ccc/AI.md"}`),a={name:`ccc/AI.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="ai" tabindex="-1">AI <a class="header-anchor" href="#ai" aria-label="Permalink to “AI”">​</a></h1><p>AI对人类的威胁能力在于工程能力的实现，LLM不能学习世界运行的规律。</p><p>Anthropic，达里奥·阿莫迪=岳不群，双标嘴巴选手。 为什么是anthropic脱颖而出，反而比openAI有更高的曝光度，实质是其背后资本集团系“绝对理性主义”团伙。</p><p>该团伙实际操作既玩嘴巴，通过NGO项目，长期资助相关领域有志于从事记者的学生，继而发展成为其喉舌，由于这些“记者”肚子里没什么墨水，实质成为该团伙的传声筒，所以导致铺天盖地都是anthropic，既anthropic本质就是嘴巴选手。</p><p>该团伙极端反华仇华。八字还没一撇，就已经在鼓吹中国将创造出AGI人工智能并导致人类毁灭。</p><p>就目前的Transformer模型来看，根本称不上智能，其实质既条件概率预测模型，给定已出现的上下文，预测下一个字的概率分布。</p><p>就算达到99.999%的准确率，只要不是100%，只要持续推理，总体的联合概率就会断崖式下跌，模型在回答问题前会迭代执行回溯，校验，还是利用概率，排除错误分支。但不解决根本问题，知其然，不知其所以然。</p><p>尽管Transformer模型有天然硬伤，但是只要数据质量提升，算力提升，损失函数就会下降，概率就会越来越大。是目前的一切工程实现中跑分一骑绝尘的存在。</p><p>从技术原理很容易发现一个问题，LLM根本不理解现实规律，完全是被动、机械的。</p>`,9)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};